// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 1, type(uint128).max);
        vm.deal(caller, amount);
        vm.prank(caller);
        uint256 balanceBefore = address(caller).balance;
        c.deposit{value: amount}();
        uint256 balanceAfter = address(caller).balance;
        assertTrue(balanceAfter == balanceBefore - amount);
    }
}

